(201, 1, '2018-10-23 07:33:09', '2018-10-23 07:33:09', '<style>/*! elementor - v3.13.3 - 28-05-2023 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>Contact Us</h2>		\n			<style>/*! elementor - v3.13.3 - 28-05-2023 */\n.elementor-widget-google_maps .elementor-widget-container{overflow:hidden}.elementor-widget-google_maps .elementor-custom-embed{line-height:0}.elementor-widget-google_maps iframe{height:300px}</style>		\n			<iframe loading=\"lazy\"\n					src=\"https://maps.google.com/maps?q=London%20Eye%2C%20London%2C%20United%20Kingdom&#038;t=m&#038;z=10&#038;output=embed&#038;iwloc=near\"\n					title=\"London Eye, London, United Kingdom\"\n					aria-label=\"London Eye, London, United Kingdom\"\n			></iframe>\n			<h2>Get in touch with us</h2>		\n		For more information about our product & Services. please\n<br />feel free to drop us an email. our staff always be there to help\n<br />you out. do not hesitate!		\n			<style>/*! elementor - v3.13.3 - 28-05-2023 */\n.elementor-widget-image{text-align:center}.elementor-widget-image a{display:inline-block}.elementor-widget-image a img[src$=\".svg\"]{width:48px}.elementor-widget-image img{vertical-align:middle;display:inline-block}</style>												<img width=\"50\" height=\"50\" src=\"http://localhost/WP_NsCraft/wp-content/uploads/2021/12/icon.png\" alt=\"\" loading=\"lazy\" />															\n			<h2>Address</h2>		\n		236 5th SE Avenue, New York <br />NY10000, United States		\n															<img width=\"50\" height=\"50\" src=\"http://localhost/WP_NsCraft/wp-content/uploads/2021/12/icon-phone.png\" alt=\"\" loading=\"lazy\" />															\n			<h2>Phone</h2>		\n		Mobile: +1 (342) 837-8276 <br />\nHotline: +1 (342) 808-8080		\n															<img width=\"50\" height=\"50\" src=\"http://localhost/WP_NsCraft/wp-content/uploads/2021/12/icon-clock.png\" alt=\"\" loading=\"lazy\" />															\n			<h2>Working Time</h2>		\n		Monday - Friday: 9:00 - 22:00 <br />\nSaturday & Sunday: 9:00 - 21:00		\n			<h5>Drop us a line</h5>		\n		[contact-form-7 id=\"213\" title=\"Contact Form\"]		\n			<style>/*! elementor - v3.13.3 - 28-05-2023 */\n.elementor-column .elementor-spacer-inner{height:var(--spacer-size)}.e-con{--container-widget-width:100%}.e-con-inner>.elementor-widget-spacer,.e-con>.elementor-widget-spacer{width:var(--container-widget-width,var(--spacer-size));--align-self:var(--container-widget-align-self,initial);--flex-shrink:0}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container,.e-con-inner>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer,.e-con>.elementor-widget-spacer>.elementor-widget-container,.e-con>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer{height:100%}.e-con-inner>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer>.elementor-spacer-inner,.e-con>.elementor-widget-spacer>.elementor-widget-container>.elementor-spacer>.elementor-spacer-inner{height:var(--container-widget-height,var(--spacer-size))}</style>', 'Contact', '', 'publish', 'closed', 'closed', '', 'contact', '', '', '2026-11-04 20:15:56', '2026-11-04 20:15:56', '', 0, 'https://woostify.com/demos/fashion1/?page_id=201', 0, 'page', '', 0),
